use serde_json::json;use sha2::{Digest,Sha256};use std::{alloc::{GlobalAlloc,Layout},sync::{atomic::{AtomicUsize,Ordering::Relaxed},Arc,Mutex},time::Instant};
use rayon::prelude::*;use zopro_core::{G1Caller,G2Caller};
enum Fixture{G1(G1Caller),G2(G2Caller)}
impl Fixture{fn new(n:usize,seed:u64,g2:bool)->Self{if g2{Self::G2(G2Caller::new(n,seed))}else{Self::G1(G1Caller::new(n,seed))}}fn reset(&mut self){match self{Self::G1(f)=>f.reset(),Self::G2(f)=>f.reset()}}fn run(&mut self,n:usize,on:bool,b:bool){match self{Self::G1(f)=>f.run(n,on,b),Self::G2(f)=>f.run(n,on,b)}}fn check(&self,n:usize){match self{Self::G1(f)=>f.check(n),Self::G2(f)=>f.check(n)}}fn capacities(&self)->[usize;2]{match self{Self::G1(f)=>f.capacities(),Self::G2(f)=>f.capacities()}}fn digest(&self)->Vec<u8>{match self{Self::G1(f)=>f.digest(),Self::G2(f)=>f.digest()}}}
mod perf;
static ALLOCS:AtomicUsize=AtomicUsize::new(0);struct Counted;unsafe impl GlobalAlloc for Counted{unsafe fn alloc(&self,l:Layout)->*mut u8{ALLOCS.fetch_add(1,Relaxed);unsafe{zopro_core::alloc::Allocator.alloc(l)}}unsafe fn alloc_zeroed(&self,l:Layout)->*mut u8{ALLOCS.fetch_add(1,Relaxed);unsafe{zopro_core::alloc::Allocator.alloc_zeroed(l)}}unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{ALLOCS.fetch_add(1,Relaxed);unsafe{zopro_core::alloc::Allocator.realloc(p,l,n)}}unsafe fn dealloc(&self,p:*mut u8,l:Layout){unsafe{zopro_core::alloc::Allocator.dealloc(p,l)}}}#[global_allocator]static A:Counted=Counted;
fn affinity(cpu:usize){unsafe{let mut mask:libc::cpu_set_t=std::mem::zeroed();libc::CPU_ZERO(&mut mask);libc::CPU_SET(cpu,&mut mask);assert_eq!(libc::sched_setaffinity(0,std::mem::size_of_val(&mask),&mask),0);}}
fn main(){
let a=std::env::args().collect::<Vec<_>>();assert_eq!(a.len(),6);let g2=match a[1].as_str(){"G1"=>false,"G2"=>true,_=>panic!("kind")};let borrowed=true;let n=a[2].parse::<usize>().unwrap();let workers=a[3].parse::<usize>().unwrap();let rounds=a[4].parse::<usize>().unwrap();let mixed=match a[5].as_str(){"OFF"=>false,"ON"=>true,_=>panic!("arm")};assert_eq!(mixed,cfg!(zopro_inverse_root_product),"wrong compiled arithmetic arm");assert!([1,16,32].contains(&workers)&&rounds>0);
let seen=Arc::new(Mutex::new(vec![]));let seen2=seen.clone();let pool=rayon::ThreadPoolBuilder::new().num_threads(workers).stack_size(512*1024).start_handler(move|i|{let cpu=if workers==1{2}else{i};affinity(cpu);seen2.lock().unwrap().push(json!({"worker":i,"cpu":cpu,"tid":unsafe{libc::syscall(libc::SYS_gettid)}}));}).build().unwrap();pool.broadcast(|_|());let mut mapping=seen.lock().unwrap().clone();mapping.sort_by_key(|x|x["worker"].as_u64().unwrap());assert_eq!(mapping.len(),workers);
let mut fixtures=(0..workers).map(|i|Fixture::new(n,19+i as u64,g2)).collect::<Vec<_>>();
for _ in 0..3{pool.install(||fixtures.par_iter_mut().for_each(|f|{f.reset();f.run(128,mixed,borrowed);f.check(128);}));}
let caps=fixtures.iter().map(|f|f.capacities()).collect::<Vec<_>>();for f in &mut fixtures{f.reset();}
let mut control=perf::Control::from_env().unwrap();if let Some(c)=control.as_mut(){c.enable().unwrap();}let usage0=perf::Usage::now().unwrap();let alloc0=ALLOCS.load(Relaxed);let start=Instant::now();pool.install(||fixtures.par_iter_mut().for_each(|f|f.run(std::hint::black_box(rounds),mixed,borrowed)));let elapsed=start.elapsed().as_nanos()as u64;let allocs=ALLOCS.load(Relaxed)-alloc0;let usage1=perf::Usage::now().unwrap();if let Some(c)=control.as_mut(){c.disable().unwrap();}
assert_eq!(allocs,0,"timed allocations");let mut h=Sha256::new();for f in &fixtures{f.check(rounds);h.update(f.digest());}let aftercaps=fixtures.iter().map(|f|f.capacities()).collect::<Vec<_>>();assert_eq!(caps,aftercaps);pool.broadcast(|ctx|assert_eq!(unsafe{libc::sched_getcpu()},if workers==1{2}else{ctx.index()}as i32));
println!("CALLER {}",json!({"kind":a[1],"size":n,"workers":workers,"rounds_per_worker":rounds,"arm":a[5],"pid":std::process::id(),"worker_rows":mapping,"elapsed_ns":elapsed,"ns_per_batch_wave":elapsed as f64/rounds as f64,"timed_allocations":allocs,"scratch_capacity_bytes_by_worker":caps,"output_sha256":format!("{:x}",h.finalize()),"complete_generator_oracle":true,"priming_passes":3,"priming_rounds":128,"usage":usage1.difference(&usage0),"new_proofs":0}));
}
